# ═══════════════════════════════════════════════════════════════════
# SOUND ENGINE — uses st.components.v1.html() so JS actually runs.
# Win/lose use real uploaded audio (base64). Others are synthesized.
# ═══════════════════════════════════════════════════════════════════

# Audio files embedded as base64 — no external files needed
_WIN_B64  = ""
_LOSE_B64 = ""

# Synthesized sound definitions: list of (freq, waveType, delay, duration, gain)
# or ("noise", delay, duration, gain) for a white-noise burst
SOUNDS = {
    "click":         [(600,  "sine",     0,    0.08, 0.30)],
    "swap":          [(440,  "triangle", 0,    0.06, 0.35),
                      (660,  "triangle", 0.07, 0.10, 0.30)],
    "no_swap":       [(320,  "sine",     0,    0.12, 0.20)],
    "timeout":       [(440,  "sawtooth", 0,    0.20, 0.30),
                      (370,  "sawtooth", 0.25, 0.20, 0.30),
                      (293,  "sawtooth", 0.50, 0.35, 0.35)],
    "heart_loss":    [("noise", 0, 0.05, 0.50),
                      (200,  "sawtooth", 0.05, 0.20, 0.40)],
    "urgent":        [(880,  "square",   0,    0.08, 0.25)],
    "merge_correct": [(523,  "sine",     0,    0.10, 0.30),
                      (784,  "sine",     0.12, 0.15, 0.30)],
    "merge_wrong":   [(220,  "sawtooth", 0,    0.15, 0.40)],
    "level_up":      [(523,  "sine",     0,    0.20, 0.35),
                      (659,  "sine",     0.09, 0.20, 0.35),
                      (784,  "sine",     0.18, 0.20, 0.35),
                      (1047, "sine",     0.27, 0.20, 0.35),
                      (1319, "sine",     0.36, 0.20, 0.35)],
}

def _build_audio_html(b64_data: str, mime: str, volume: float) -> str:
    """Play a real audio file embedded as base64."""
    return f"""<html><body>
<script>
(function() {{
    var audio = new Audio('data:{mime};base64,{b64_data}');
    audio.volume = {volume:.2f};
    audio.play().catch(function(e) {{ console.warn('audio play error:', e); }});
}})();
</script>
</body></html>"""

def _build_synth_html(name: str, volume: float) -> str:
    """Build a self-contained HTML snippet that synthesizes and plays a sound."""
    notes = SOUNDS.get(name, [])
    js_parts = []
    for note in notes:
        if note[0] == "noise":
            _, delay, dur, gain = note
            js_parts.append(f"""
(function(){{
    var bufSize = ctx.sampleRate * {dur};
    var buf = ctx.createBuffer(1, bufSize, ctx.sampleRate);
    var data = buf.getChannelData(0);
    for(var i=0;i<bufSize;i++) data[i]=Math.random()*2-1;
    var src = ctx.createBufferSource();
    src.buffer = buf;
    var g = ctx.createGain();
    g.gain.setValueAtTime({gain * volume:.3f}, t + {delay});
    g.gain.exponentialRampToValueAtTime(0.001, t + {delay} + {dur});
    src.connect(g); g.connect(ctx.destination);
    src.start(t + {delay}); src.stop(t + {delay} + {dur} + 0.01);
}})();""")
        else:
            freq, wtype, delay, dur, gain = note
            js_parts.append(f"""
(function(){{
    var osc = ctx.createOscillator();
    var g = ctx.createGain();
    osc.type = '{wtype}';
    osc.frequency.setValueAtTime({freq}, t + {delay});
    g.gain.setValueAtTime({gain * volume:.3f}, t + {delay});
    g.gain.exponentialRampToValueAtTime(0.001, t + {delay} + {dur});
    osc.connect(g); g.connect(ctx.destination);
    osc.start(t + {delay}); osc.stop(t + {delay} + {dur} + 0.01);
}})();""")

    js_body = "\n".join(js_parts)
    return f"""<html><body><script>
try {{
    var ctx = new (window.AudioContext || window.webkitAudioContext)();
    var t = ctx.currentTime + 0.01;
    {js_body}
}} catch(e) {{ console.warn('BrainSort sound error:', e); }}
</script></body></html>"""


def inject_sound_engine():
    """No-op — engine is embedded per sound call."""
    pass


def play_sound(name: str):
    """Play a sound effect using a hidden zero-height iframe component."""
    if not st.session_state.get("sound_enabled", False):
        return
    vol = st.session_state.get("sfx_volume", 50) / 100.0
    if name in ("win", "level_up"):
        html = _build_audio_html(_WIN_B64, "audio/mpeg", vol)
    elif name in ("timeout", "heart_loss", "merge_wrong"):
        html = _build_audio_html(_LOSE_B64, "audio/mpeg", vol)
    else:
        html = _build_synth_html(name, vol)
    components.html(html, height=0, scrolling=False)

