# BUBBLE SORT: Generate numbers
# ═══════════════════════════════════════════════════════════════════
def make_numbers(level):
    numbers = []
    if level == "easy":
        numbers = random.sample(range(1, 20), 6)
        numbers.sort()
        i = 0
        while i < len(numbers) - 1:
            temp = numbers[i]
            numbers[i] = numbers[i + 1]
            numbers[i + 1] = temp
            i = i + 2
    if level == "medium":
        numbers = random.sample(range(1, 30), 12)
        numbers.sort()
        for i in range(len(numbers)):
            chance = random.random()
            if chance < 0.5:
                j = random.randint(0, len(numbers) - 1)
                temp = numbers[i]
                numbers[i] = numbers[j]
                numbers[j] = temp
    if level == "hard":
        numbers = random.sample(range(1, 40), 24)
        random.shuffle(numbers)
        count = 0
        while count < len(numbers):
            i = random.randint(0, len(numbers) - 2)
            chance = random.random()
            if chance < 0.7:
                temp = numbers[i]
                numbers[i] = numbers[i + 1]
                numbers[i + 1] = temp
            count = count + 1
    return numbers

