# BUBBLE SORT: MEDIUM MODE timer bar (countdown)
# ═══════════════════════════════════════════════════════════════════
def show_medium_timer_bar():
    theme = get_theme()
    if st.session_state.medium_timer_start is None or st.session_state.medium_timer_limit is None:
        return
    elapsed = time.time() - st.session_state.medium_timer_start
    time_left = max(0, st.session_state.medium_timer_limit - elapsed)
    mins = int(time_left) // 60
    secs = int(time_left) % 60
    percent = (time_left / st.session_state.medium_timer_limit) * 100
    bar_color = theme['success']
    if time_left < (st.session_state.medium_timer_limit * 0.33):
        bar_color = theme['warning']
    if time_left < 10:
        bar_color = theme['danger']

    # Urgent warning styling
    urgent_class = "urgent-timer-box" if time_left <= 30 and time_left > 0 else ""
    if time_left <= 30 and time_left > 0:
        show_urgent_warning()
    if time_left <= 10 and time_left > 0:
        play_sound("urgent")

    st.markdown(f"""
        <div style="margin-bottom:16px;" class="{urgent_class}">
            <div style="display:inline-flex; align-items:center; gap:10px; background:rgba(0,0,0,0.35); border-radius:999px; padding:8px 22px; border:1px solid rgba(255,208,0,0.4);">
                <span style="font-size:20px;">⏱</span>
                <span style="font-size:26px; font-weight:800; font-family:monospace; color:{theme['accent']}; letter-spacing:2px;">{mins:02d}:{secs:02d}</span>
                <span style="font-size:10px; color:{theme['text_muted']}; letter-spacing:3px;">REMAINING</span>
            </div>
            <div style="height:10px; background:rgba(255,255,255,0.15); border-radius:999px; overflow:hidden; margin-top:8px;">
                <div class="timer-bar" style="height:100%; width:{percent:.1f}%; background:{bar_color}; border-radius:999px;"></div>
            </div>
        </div>
    """, unsafe_allow_html=True)


