        "&nbsp;&nbsp;left = merge_sort(arr[:mid])",
        "&nbsp;&nbsp;right = merge_sort(arr[mid:])",
        "&nbsp;&nbsp;return merge(left, right)",
        "&nbsp;",
        "def merge(left, right):",
        "&nbsp;&nbsp;result = []",
        "&nbsp;&nbsp;while left and right:",
